insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('c3e6011b-53b9-5f67-a247-e74eba76db15', 'reverse-lunge', 'Reverse Lunge', array['quadriceps', 'glutes']::text[], array['hamstrings', 'core']::text[], array['bodyweight', 'dumbbell']::text[], 'strength', 'lunge', 'compound', 'beginner', false, false, 'Stepping backward into a lunge — typically more knee-friendly than forward lunges.', array['Stand tall with feet hip width apart.', 'Step one foot back and lower until the back knee hovers above the floor.', 'Keep most of your weight in the front foot.', 'Push through the front foot to return to standing.']::text[], array['Step back far enough', 'Front heel heavy', 'Torso tall']::text[], array['Narrow tightrope stance', 'Pushing off the back foot', 'Knee slamming down']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
