insert into public.exercises (id, slug, name, primary_muscles, secondary_muscles, equipment, category, movement_pattern, mechanics, difficulty, is_timed, low_impact, description, instructions, form_cues, common_mistakes, is_published) values ('4d46cb36-e0a0-506e-a7bb-d9bfe7d31814', 'overhead-press', 'Standing Overhead Press', array['shoulders', 'triceps']::text[], array['upper chest', 'core', 'upper back']::text[], array['barbell', 'rack']::text[], 'strength', 'vertical_push', 'compound', 'intermediate', false, false, 'Pressing a barbell from the shoulders to overhead while standing.', array['Unrack the bar at collarbone height with hands just outside shoulder width.', 'Squeeze your glutes and brace your core.', 'Press the bar straight up, moving your head back slightly to let it pass.', 'Finish with the bar over mid-foot and your head through, then lower to the shoulders.']::text[], array['Glutes tight', 'Bar path straight', 'Head through at the top']::text[], array['Leaning back excessively', 'Pressing the bar forward', 'Losing the brace']::text[], true) on conflict (slug) do update set name = excluded.name, primary_muscles = excluded.primary_muscles, secondary_muscles = excluded.secondary_muscles, equipment = excluded.equipment, category = excluded.category, movement_pattern = excluded.movement_pattern, mechanics = excluded.mechanics, difficulty = excluded.difficulty, is_timed = excluded.is_timed, low_impact = excluded.low_impact, description = excluded.description, instructions = excluded.instructions, form_cues = excluded.form_cues, common_mistakes = excluded.common_mistakes;
