insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('af7935d1-c0fb-5439-9713-e67d19621af8', 'active-aging-strength-2-day', 'Strong for Life: 2-Day Strength (50+)', 'Two progressive strength sessions a week that build from light sets of 12 to heavier sets of 6–8.', 'For active adults over 50 who want real strength, not just movement. Research such as the LIFTMOR trial shows that supervised, progressive, genuinely challenging lifting is safe for many older adults and improves bone density and function — so this plan moves from learning sets of 10–12 to heavier sets of 6–8 with 2–3 reps in reserve. Two sessions meet the WHO/ACSM minimum for muscle strengthening; add balance work and 150 minutes of walking or other moderate activity across the week. Get medical clearance first if you have a heart, bone or joint condition.', '5225ea79-fbe6-5abc-819f-3349cce2461e', 'beginner', 8, 2, 30, array['general_health', 'build_strength', 'build_muscle', 'type:strength', 'type:low_impact']::text[], array['dumbbell', 'bench', 'band']::text[], 'plus', 'Weeks 1–3: sets of 10–12, adding a set by week 2. Week 4 is lighter. Weeks 5–7: heavier sets of 6–8 — add a little weight whenever every set reaches 8 reps with 2–3 reps still in the tank. Week 8 is lighter again before you repeat the cycle.', array['3–5 minutes standing march or easy walk', 'Cat-cow × 8 slow breaths', 'Sit-to-stand × 5, slow and controlled', 'Arm circles × 10 each direction']::text[], array['Slow walk 2–3 minutes', 'Seated hamstring stretch 30 seconds per side', 'Slow breathing 1 minute']::text[], true, true, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
