insert into public.program_days (id, week_id, day_number, name, focus, estimated_minutes, warmup, cooldown) values ('5bf0c394-d0d9-533e-a311-50219a5d559f', '135d1131-6b5b-5c12-a95f-b26ffcfa8b80', 3, 'Workout B', 'Squat, overhead press, row', 45, array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[]);
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('5bf0c394-d0d9-533e-a311-50219a5d559f', '48e2051d-9493-5969-a85a-34c1d3d1d2ab', 0, 3, '5', null, 180, 'Smallest jump you can make; reset 10% after 3 stalls', null, 'Same rule: all reps made → add weight next session.');
