insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('5bf0c394-d0d9-533e-a311-50219a5d559f', '575567b6-8829-584c-866b-1598e3f22613', 2, 3, '5', null, 120, 'Smallest jump you can make; reset 10% after 3 stalls', null, 'If you''ve been coached on it, power cleans (5 × 3) can replace rows.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('5bf0c394-d0d9-533e-a311-50219a5d559f', 'd128d1f4-47de-5672-9510-1999638d6609', 3, 2, '10', null, 75, null, null, 'Builds the lower back and glutes for the deadlift.');
insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('b0be670b-898b-53d4-9f76-644956bcbc1b', 'tiered-strength-program', 'Tiered Strength: Heavy, Volume & Pump', 'Four days built on three tiers — heavy triples, sets of ten and high-rep pump work — with a set rule for every stall.', 'A tiered linear progression in the style of Cody Lefever''s GZCLP. Each day pairs one main lift for heavy, low-rep work (tier 1) with a different main lift for volume (tier 2) and a high-rep upper-back exercise (tier 3), so every lift gets trained heavy once and for volume once a week. When a lift stalls you change the set-and-rep scheme instead of stopping — which keeps late-novice lifters progressing for months.', '42a6d9d6-53e5-5755-8274-3a0b73c46fb9', 'beginner', 12, 4, 40, array['build_strength', 'build_muscle', 'type:strength', 'type:powerlifting']::text[], array['barbell', 'rack', 'bench', 'cable', 'dumbbell']::text[], 'plus', 'Tier 1 (5 × 3, last set as many as possible): add 2.5 kg / 5 lb upper, 5 kg / 10 lb lower every session. On a miss go to 6 × 2, then 10 × 1, then test a 5-rep max and restart 5 × 3 at 85% of it. Tier 2 (3 × 10): add weight every session; on a miss go to 3 × 8, then 3 × 6, then restart 3 × 10 about 5–10% lighter than your last 3 × 10. Tier 3 (3 × 15+): add weight when the last set reaches 25 reps. Weeks 6 and 12 are deloads.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
insert into public.program_weeks (id, program_id, week_number, focus, is_deload) values ('cfc813dd-0407-5c2e-88d5-6a5931a823d7', 'b0be670b-898b-53d4-9f76-644956bcbc1b', 1, 'Stage 1: add weight every session on every tier', false);
insert into public.program_days (id, week_id, day_number, name, focus, estimated_minutes, warmup, cooldown) values ('cbb417aa-8133-56d4-aecb-47feb686dab0', 'cfc813dd-0407-5c2e-88d5-6a5931a823d7', 1, 'Day 1 — Squat T1', 'Heavy squat, bench volume, lat pump', 40, array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[]);
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('cbb417aa-8133-56d4-aecb-47feb686dab0', '48e2051d-9493-5969-a85a-34c1d3d1d2ab', 0, 5, '3 (last set 3+)', null, 180, null, null, 'T1: 5 × 3, last set as many reps as possible. Add weight every session. Miss? Next time 6 × 2, then 10 × 1, then retest a 5-rep max and restart at 85% of it.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('cbb417aa-8133-56d4-aecb-47feb686dab0', 'c0443b25-7af2-52c2-8108-0db3e6b13309', 1, 3, '10', null, 120, null, null, 'T2: 3 × 10, add weight every session. Miss? Move to 3 × 8, then 3 × 6, then restart at a lighter 3 × 10.');
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('cbb417aa-8133-56d4-aecb-47feb686dab0', 'ad2a1bd2-4f4c-590a-b298-b5389dd9fa45', 2, 3, '15 (last set 15+)', null, 60, null, null, 'T3: same weight until the last set reaches 25 reps, then add weight.');
