insert into public.program_days (id, week_id, day_number, name, focus, estimated_minutes, warmup, cooldown) values ('339fdcc0-fc22-5967-bed7-ae521ea24b12', '5d03d988-117f-5c84-b167-9212ed6141e5', 1, 'Press Day', '5s week: main lift, 5 × 10 of the opposite lift, assistance', 55, array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[]);
