insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('425af2c2-eaf8-5d2a-86dc-6edf2e8fb1e6', 'powerbuilding-4-day', 'Powerbuilding 4-Day: Strength + Size', 'Two heavy days and two hypertrophy days a week: get stronger on the big lifts while building muscle everywhere.', 'Powerbuilding blends a powerlifter''s heavy compound work with a bodybuilder''s volume. Strength days use 4–6 reps on the squat, bench and rows; hypertrophy days use 8–20 reps, machines, cables and lengthened-position exercises. Weekly volume lands around 10–20 hard sets per major muscle and builds through two three-week waves, each followed by a deload.', '9a638901-5307-5e5b-8a1b-39a7008089b5', 'intermediate', 8, 4, 55, array['build_strength', 'build_muscle', 'type:strength', 'type:hypertrophy']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable', 'machine', 'pull_up_bar']::text[], 'plus', 'Heavy lifts: add 2.5 kg / 5 lb when every set reaches the top of the rep range at the target RPE. Hypertrophy work: double progression — add reps, then load. Each wave starts at about 3 reps in reserve and ends around 1, with an extra set on key exercises; weeks 4 and 8 halve the sets.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
