insert into public.program_days (id, week_id, day_number, name, focus, estimated_minutes, warmup, cooldown) values ('0480c289-7332-5c48-ab2c-604546356d50', '5884030b-910a-5a0c-bd74-d4db3c0e27f2', 1, 'Max-Effort Lower', 'Heavy squat or pull variation, then posterior chain', 50, array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[]);
insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('0480c289-7332-5c48-ab2c-604546356d50', '9942894f-f006-5cfd-9772-6f300523bae1', 0, 3, '1-3 top + 2 × 3', null, 240, null, 9, 'Max effort: work up in small jumps to a 1–3 rep max for today (RPE 9, no grinders), then 2 back-off triples at about 85% of it. The exercise rotates every 2 weeks so you can push it hard without stalling.');
