insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('cd4c0feb-1630-51a0-b38a-2e5722da17dd', 'powerlifting-peaking-12-week', '12-Week Powerlifting Peak', 'Accumulation, intensification, a two-week taper and meet week — with attempt selection built in.', 'A block-periodized meet prep. Four weeks of volume at 70–77.5%, a deload, four weeks of triples at 80–87.5%, a peak week of heavy singles, a taper that cuts volume by about half while keeping intensity (the approach supported by tapering research for strength athletes), and meet week. Bench is trained three times a week, squat twice and the deadlift twice with the last heavy pull about ten days out. Meet day uses the common attempt rule: an opener you could triple on a bad day (90–92%), a second at 95–97%, and a third at 100–103% only if the second moved well.', '355ad483-2f7b-50b3-b6ce-6ac1400d6063', 'advanced', 12, 4, 50, array['build_strength', 'type:powerlifting', 'type:strength']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable', 'machine', 'pull_up_bar']::text[], 'plus', 'Percentages are of your current 1RM and rise 2.5% a week through each phase. If a set is more than 1 RPE above target, stay at that weight. Week 5 deloads; weeks 10–11 peak and taper (volume down 40–50%, intensity held); week 12 is meet week.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
