insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('611ce852-1855-568c-b839-4cfc3a501f98', 'strongman-foundations', 'Strongman Foundations', 'Build odd-object strength, carries and pressing power with gym-accessible tools.', 'A strongman program that uses equipment found in many gyms — sandbags, sleds, dumbbells and barbells — as substitutes for the log, circus dumbbell, stones, yoke and truck pull. Two max-effort days (overhead and deadlift) plus an odd-object day, with carries and drags programmed by distance and target time — the way competitive strongmen structure their weeks. Have real implements? Try Strongman 4-Day: Statics & Events.', '813b72f1-cbac-52f4-8034-3cf0560cfa7f', 'beginner', 6, 3, 55, array['build_strength', 'athletic_performance', 'type:strongman', 'type:strength']::text[], array['barbell', 'rack', 'sandbag', 'sled', 'dumbbell', 'kettlebell']::text[], 'free', 'Moving events progress by load: when every run beats the target time with good posture, add weight next week. Pressing and pulling follow RPE progression (capped at RPE 9). Week 6 deloads volume by about 40%.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
