insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('24344681-fbbb-5031-86b3-7644ed4f360a', 'power-hypertrophy-upper-lower', 'Power & Hypertrophy Upper/Lower (4 Days)', 'Two heavy 3–5 rep days and two 8–15 rep days — each muscle twice a week, strength and size together.', 'In the style of Brandon Campbell''s PHUL: upper and lower power days built on heavy compounds, then upper and lower hypertrophy days with more isolation work. A popular next step after a novice program for lifters who want to look and perform better.', '8f19916a-c1e0-5027-887e-6f78ca07b045', 'intermediate', 6, 4, 55, array['build_muscle', 'build_strength', 'type:hypertrophy', 'type:strength']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable', 'machine', 'pull_up_bar']::text[], 'plus', 'Power days: add 2.5 kg / 5 lb when every set reaches 5 reps at the target RPE. Hypertrophy days: double progression. Weeks 3–5 add a set to key exercises as reps in reserve fall from 3 to about 1; week 6 is a deload.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
