insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('c75e5559-9876-5256-a6cb-da9fd59bb5bd', 'push-pull-legs-6-day', 'Push / Pull / Legs: 6 Days', 'Push, pull and legs twice a week: a heavy lift with a last-set rep target, then bodybuilding volume.', 'In the style of the popular Reddit PPL by u/metallicadpa: each day opens with a main lift (deadlift, bench, squat, row or overhead press) and a last set for as many reps as possible, then moves to 8–20 rep accessories. Six days give every muscle two sessions a week with about 12–18 hard sets. Run it Push-Pull-Legs-Push-Pull-Legs-Rest, or put the rest day after the first three.', '8f19916a-c1e0-5027-887e-6f78ca07b045', 'intermediate', 6, 6, 45, array['build_muscle', 'build_strength', 'type:hypertrophy', 'type:strength']::text[], array['barbell', 'rack', 'bench', 'dumbbell', 'cable', 'machine', 'pull_up_bar']::text[], 'plus', 'Main lifts: when the last set reaches 5+ reps (deadlift: 5+ on its single set), add 2.5 kg / 5 lb (deadlift 5 kg / 10 lb) next time; miss three times and drop 10%. Accessories: double progression. Weeks 3–5 add a set to key accessories; week 6 is a deload.', array['3–5 minutes easy cardio (walk, bike, rower or skipping)', 'World''s greatest stretch × 3 per side', 'Bodyweight squats × 10', 'Band pull-aparts or arm circles × 15', '2–3 ramp-up sets of your first lift, building toward working weight']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
