insert into public.program_exercises (day_id, exercise_id, position, sets, reps, duration_seconds, rest_seconds, intensity, rpe, notes) values ('818365c4-d9a0-5b68-9443-8eee1a85b7ed', '3d6e2331-9349-59f9-9824-5452ccb938e2', 5, 1, null, 1200, 0, null, null, 'Mandatory poses, quarter turns and transitions for your division; hold each pose 10–20 s. Practise every day now, rest days included.');
insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('f3a4e369-ffff-5d76-9fad-8e9c0d078084', 'mma-off-camp-2-day', 'Off-Camp Strength for Fighters (2 Days)', 'Two short strength & power sessions a week that build a base without stealing from skills training.', 'Between fight camps, most of your energy should go to skills. Two full-body sessions a week are enough to build and keep strength, power and resilience: jumps and throws first, then a heavy lower-body lift, pressing and pulling, hamstring and groin injury-prevention work, and neck training (stronger necks are associated with lower concussion risk in observational research). Everything stays 2–3 reps shy of failure to keep soreness low — lift after technique work or 6+ hours apart.', '6d7b7a89-48be-5e4d-8177-56b5b31efe3f', 'beginner', 8, 2, 35, array['combat_sports', 'build_strength', 'athletic_performance', 'type:mma', 'type:athletic', 'type:grappling', 'type:boxing']::text[], array['barbell', 'trap_bar', 'dumbbell', 'medicine_ball', 'box', 'pull_up_bar', 'bench', 'rack']::text[], 'free', 'Weeks 1–3: sets of 5, adding a set and a little load. Week 4 deloads. Weeks 5–7: heavier triples at the same low soreness. Week 8 deloads. Neck and groin work progress by 5 seconds or 2 reps a week, never through pain.', array['5 minutes jump rope or easy shadowboxing', 'Hip openers, neck circles and world''s greatest stretch × 3 per side', '2 × 10-second build-up efforts']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
