insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('a94ca269-561a-5ada-82c6-ad244b26a04a', 'boxing-round-ready', 'Boxing: Round Ready', 'Shoulder endurance, footwork and repeat-sprint capacity for boxing.', 'Round-structured sessions that mirror the demands of boxing: sustained shoulder output, light fast feet and the ability to recover between exchanges. Pair with technical boxing coaching.', '0e4ef220-a938-56bd-bcc7-ad44050cda03', 'beginner', 4, 3, 45, array['combat_sports', 'improve_conditioning', 'lose_fat', 'type:boxing', 'type:cardio']::text[], array['jump_rope', 'heavy_bag', 'dumbbell', 'medicine_ball', 'bodyweight']::text[], 'plus', 'Conditioning adds a round or cuts 10 seconds of rest each week; strength work holds at about RPE 7. Week 4 keeps rounds but lowers intensity.', array['5 minutes easy jump rope, bike or shadowboxing', 'Lateral shuffles × 20 seconds each way', 'World''s greatest stretch × 3 per side', '2 × 10-second build-up efforts at moderate intensity']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
