insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('026cd113-4195-55af-8191-57b69ecb5744', 'grappling-mat-endurance', 'Wrestling & Grappling: Mat Endurance', 'Grip, hips, and repeat-effort endurance for wrestling, BJJ and judo.', 'Grapplers need strength-endurance in awkward positions, a crushing grip, pressing strength for frames and posts, and the ability to repeat scrambles. These sessions build exactly that while protecting the neck and lower back with controlled loading.', '993f5cf7-af86-5577-ba12-903b74650e31', 'intermediate', 4, 3, 45, array['combat_sports', 'improve_conditioning', 'type:grappling', 'type:mma']::text[], array['kettlebell', 'sandbag', 'pull_up_bar', 'mat', 'barbell', 'dumbbell', 'landmine']::text[], 'plus', 'Conditioning intervals add a round or cut 10 seconds of rest each week; lifts hold at RPE 7–8. Week 4 reduces volume by a third.', array['5 minutes easy jump rope, bike or shadowboxing', 'Lateral shuffles × 20 seconds each way', 'World''s greatest stretch × 3 per side', '2 × 10-second build-up efforts at moderate intensity', 'Hip escapes × 6 per side']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
