insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('f53e709d-8afc-59c4-bf76-ea600e99aa79', 'combat-conditioning-sessions', 'Combat Conditioning Session Library', 'Six stand-alone sessions — pick 1–2 a week: grappling, wrestling, striking, anaerobic, aerobic and footwork.', 'Choose the session that complements your skill training that day. Each one targets a specific quality — don''t do them all in one week. Hard anaerobic sessions should be 48 hours away from hard sparring.', '6d7b7a89-48be-5e4d-8177-56b5b31efe3f', 'intermediate', 1, 6, 45, array['combat_sports', 'improve_conditioning', 'type:mma', 'type:boxing', 'type:grappling']::text[], array['kettlebell', 'sandbag', 'pull_up_bar', 'mat', 'bike', 'rower', 'jump_rope', 'heavy_bag']::text[], 'plus', 'Repeat any session weekly, adding a round or reducing rest by 10 seconds when output holds steady.', array['5 minutes easy jump rope, bike or shadowboxing', 'Lateral shuffles × 20 seconds each way', 'World''s greatest stretch × 3 per side', '2 × 10-second build-up efforts at moderate intensity']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, true, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldo