insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('5d7edfb6-d704-5c98-9baa-4061e94e15cb', 'walk-to-run-beginner', 'Walk to Run: 6 Weeks to Your First 20-Minute Jog', 'Three gentle sessions a week take you from brisk walking with short jogs to 20 minutes of continuous easy jogging.', 'For complete beginners or anyone returning after a long break, before the First 5K plan. Two walk/jog interval sessions and one brisk walk each week; the jogging bits grow from 30 seconds to 3 minutes, and the last session is 20 minutes of easy, continuous jogging. Everything is conversational. Repeat any week that leaves you sore or out of breath, and stop if anything hurts.', 'd4e79e61-b816-5c53-a64a-537abe13101d', 'beginner', 6, 3, 30, array['improve_conditioning', 'general_health', 'lose_fat', 'type:cardio']::text[], array['bodyweight']::text[], 'free', 'Jog intervals lengthen each week (30 s → 3 min) while walk breaks shorten; the brisk walk grows to 40 minutes. Week 6 ends with a 20-minute jog.', array['5 minutes brisk walking', 'Ankle circles × 10 each direction']::text[], array['5 minutes easy walking', 'Calf stretch — 30 seconds per side']::text[], true, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
