insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('3621bf3c-cadd-585e-a37e-d02a455ca67a', '5k-training', '5K Training: Run Your Best 5K', 'Eight weeks, three runs a week: easy running, one quality session, a long run, a cutback week and a race-week taper.', 'For runners who can already run 25–30 minutes without stopping. Most running is easy and conversational; one session a week sharpens your 5K pace with short repeats, then longer 5K-effort repeats. The long run builds to about 55 minutes. Week 4 cuts back, and week 8 tapers into a 5K time trial or race.', 'd4e79e61-b816-5c53-a64a-537abe13101d', 'intermediate', 8, 3, 40, array['improve_conditioning', 'general_health', 'type:cardio']::text[], array['bodyweight']::text[], 'plus', 'Repeats move from 6–8 × 1 min (weeks 1–3) to 4–5 × 3 min at 5K effort (5–7); easy and long runs grow most weeks. Week 4 cuts back; week 8 tapers.', array['5 minutes brisk walk or very easy jog', 'Leg swings × 10 each leg', 'A-skips × 20 m and 2 relaxed strides']::text[], array['5 minutes easy walking', 'Calf stretch — 30 seconds per side', 'Standing quad stretch — 30 seconds per side']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
