insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('cb630614-78b9-5ce9-a987-a996961e2d11', 'athletic-qualities-sessions', 'Athletic Qualities Session Library', 'Four focused sessions — pick 1–2 a week: explosive power, rotational core, grip endurance, sport-specific strength.', 'Plug-in sessions to target a specific athletic quality. Use one or two per week alongside your sport or main program.', 'f708f087-cda3-534e-bff4-d71485e31190', 'intermediate', 1, 4, 40, array['athletic_performance', 'combat_sports', 'type:athletic', 'type:mma', 'type:strength']::text[], array['barbell', 'medicine_ball', 'box', 'cable', 'band', 'pull_up_bar', 'dumbbell', 'kettlebell', 'trap_bar', 'landmine']::text[], 'plus', 'Power: stop sets when speed drops. Strength: RPE progression. Grip: add 5 seconds per hold weekly.', array['5 minutes easy jump rope, bike or shadowboxing', 'Lateral shuffles × 20 seconds each way', 'World''s greatest stretch × 3 per side', '2 × 10-second build-up efforts at moderate intensity']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
