insert into public.training_programs (id, slug, name, summary, description, category_id, difficulty, duration_weeks, days_per_week, session_minutes, goals, equipment, tier, progression, warmup, cooldown, low_impact, needs_specialist_review, is_published, source) values ('2e8640b8-5ce6-52fe-95d1-5f9edbfbbbb6', 'calisthenics-strength-upper-lower', 'Calisthenics Strength: Upper / Lower', 'Four sessions a week for people who can already do pull-ups and dips: weighted-progression upper days and single-leg lower days.', 'For trainees with 3+ strict pull-ups and 5+ dips. Upper days pair vertical and horizontal pulling with dips and pike push-ups; lower days use single-leg squats, Nordic curls and Copenhagen planks so legs keep up without a barbell. Strength comes from low-rep sets taken 1–3 reps short of failure; add load with a backpack or move to a harder variation when the top of the range is easy.', '9dd43e10-2cb8-514b-9368-7d6645f24325', 'intermediate', 8, 4, 45, array['build_strength', 'build_muscle', 'athletic_performance', 'type:strength', 'type:home']::text[], array['bodyweight', 'pull_up_bar', 'dip_station', 'bench', 'mat']::text[], 'plus', 'Upper days: 4 sets of 5–8. When every set reaches 8, add 2–5 kg in a backpack or a harder variation. Lower days add reps, then slow the lowering to 3 seconds. Sets rise in the second half of each block; weeks 4 and 8 are deloads.', array['3 minutes skipping or easy jog', 'Wrist and shoulder circles × 10', 'Scapular pull-ups × 8', 'Bodyweight squats × 10', 'Push-ups × 5 and a 20-second dead hang']::text[], array['3–5 minutes easy walking or cycling to bring heart rate down', 'Child''s pose — 60 seconds', 'Figure-four glute stretch — 30–45 seconds per side', 'Slow nasal breathing — 1–2 minutes']::text[], false, false, true, 'curated') on conflict (slug) do update set name = excluded.name, summary = excluded.summary, description = excluded.description, category_id = excluded.category_id, difficulty = excluded.difficulty, duration_weeks = excluded.duration_weeks, days_per_week = excluded.days_per_week, session_minutes = excluded.session_minutes, goals = excluded.goals, equipment = excluded.equipment, tier = excluded.tier, progression = excluded.progression, warmup = excluded.warmup, cooldown = excluded.cooldown, low_impact = excluded.low_impact, needs_specialist_review = excluded.needs_specialist_review, is_published = true;
insert into public.program_weeks (id, program_id, week_number, focus, is_deload) values ('933f12da-cfab-5ac9-8786-21100c000036', '2e8640b8-5ce6-52fe-95d1-5f9edbfbbbb6', 1, 'Block 1: own every rep in the range, about 3 reps in reserve', false);
