  for select to authenticated using (public.is_admin());

-- ---------------------------------------------------------------------------
-- Aggregate, privacy-preserving metrics for admins (counts only, no row data).
-- ---------------------------------------------------------------------------
create or replace function public.admin_usage_metrics()
returns table (
  total_users bigint,
  onboarded_users bigint,
  workouts_last_7d bigint,
  workouts_last_30d bigint,
  active_users_30d bigint,
  ai_requests_30d bigint,
  plus_subscribers bigint,
  pro_subscribers bigint
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  return query
  select
    (select count(*) from public.profiles),
    (select count(*) from public.profiles where onboarding_completed_at is not null),
    (select count(*) from public.workout_sessions where status = 'completed' and started_at > now() - interval '7 days'),
    (select count(*) from public.workout_sessions where status = 'completed' and started_at > now() - interval '30 days'),
    (select count(distinct user_id) from public.workout_sessions where started_at > now() - interval '30 days'),
    (select count(*) from public.ai_usage_events where created_at > now() - interval '30 days'),
    (select count(*) from public.user_entitlements where plan = 'plus'),
    (select count(*) from public.user_entitlements where plan = 'pro');
end;
$$;

revoke execute on function public.admin_usage_metrics() from anon, public;
grant execute on function public.admin_usage_metrics() to authenticated;

-- ===== supabase/migrations/20261016000003_storage.sql =====
-- Storage buckets
-- avatars: private; each user can only touch objects under "<their uid>/..."
-- exercise-media: public read of licensed demonstration media; admin write.

on conflict (id) do nothing;

create policy avatars_owner_select on storage.objects
  for select to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy avatars_owner_insert on storage.objects
  for insert to authenticated
  with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy avatars_owner_update on storage.objects
  for update to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy avatars_owner_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy exercise_media_public_read on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'exercise-media');
create policy exercise_media_admin_write on storage.objects
  for all to authenticated
  using (bucket_id = 'exercise-media' and public.is_admin())
  with check (bucket_id = 'exercise-media' and public.is_admin());

-- ===== supabase/migrations/20261017000001_custom_programs.sql =====
-- Custom program builder (/train/build): users can save private programs with source = 'custom'.
-- Custom programs follow the same rules as starter and AI programs: private to their owner,
-- never published, and free for the owner.

alter table public.training_programs drop constraint if exists training_programs_source_check;
alter table public.training_programs
  add constraint training_programs_source_check check (source in ('curated', 'starter', 'ai', 'custom'));

drop policy if exists training_programs_insert on public.training_programs;
create policy training_programs_insert on public.training_programs
  for insert to authenticated with check (
    (owner_id = (select auth.uid()) and is_published = false and source in ('starter', 'ai', 'custom'))
    or (owner_id is null and public.is_admin())
  );

-- Supports the per-user build rate limit (recent custom programs by owner).
create index if not exists training_programs_owner_source_created_idx
  on public.training_programs (owner_id, source, created_at desc)
  where owner_id is not null;

-- ===== supabase/migrations/20261017000002_progress_photos.sql =====
-- Progress photos (private)
-- Each photo is an object in the PRIVATE `progress-photos` bucket under "<uid>/...",
-- plus a metadata row in public.progress_photos. Only the owner can see or change
-- either. Admins get NO access to other users' photos (no is_admin() clause anywhere).

create table public.progress_photos (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  storage_path text not null unique check (char_length(storage_path) between 3 and 300),
  taken_on date not null default current_date,
  pose text not null default 'front' check (pose in ('front', 'side', 'back', 'other')),
  weight_kg numeric(5, 2) check (weight_kg between 25 and 400),
  note text check (char_length(note) <= 280),
  created_at timestamptz not null default now(),
  -- The object must live in the owner's own folder.
  check (split_part(storage_path, '/', 1) = user_id::text)
);
create index progress_photos_user_idx on public.progress_photos (user_id, taken_on desc);

alter table public.progress_photos enable row level security;

create policy progress_photos_select_own on public.progress_photos
  for select to authenticated using (user_id = (select auth.uid()));
create policy progress_photos_insert_own on public.progress_photos
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy progress_photos_update_own on public.progress_photos
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy progress_photos_delete_own on public.progress_photos
  for delete to authenticated using (user_id = (select auth.uid()));

-- Storage bucket: private, images only, 8 MB max per object.
values ('progress-photos', 'progress-photos', false, 8388608, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

create policy progress_photos_owner_select on storage.objects
  for select to authenticated
  using (bucket_id = 'progress-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy progress_photos_owner_insert on storage.objects
  for insert to authenticated
  with check (bucket_id = 'progress-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy progress_photos_owner_update on storage.objects
  for update to authenticated
  using (bucket_id = 'progress-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy progress_photos_owner_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'progress-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- ===== supabase/migrations/20261017000003_challenges.sql =====
-- Narrow Gate Fitness — faith & fitness challenges ("40 Days Through the Narrow Gate").
-- Part of the optional Faith section. Rows are private to their owner (no admin access).

create table public.challenge_enrollments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  challenge_slug text not null check (char_length(challenge_slug) between 1 and 64),
  started_on date not null,
  status text not null default 'active' check (status in ('active', 'completed', 'abandoned')),
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  check (status <> 'completed' or completed_at is not null)
);
-- At most one active enrollment per user and challenge.
create unique index challenge_enrollments_one_active_idx
  on public.challenge_enrollments (user_id, challenge_slug) where status = 'active';
create index challenge_enrollments_user_idx on public.challenge_enrollments (user_id, created_at desc);

create table public.challenge_checkins (
  id uuid primary key default gen_random_uuid(),
  enrollment_id uuid not null references public.challenge_enrollments (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  day_number smallint not null check (day_number between 1 and 40),
  devotional_done boolean not null default false,
  workout_done boolean not null default false,
  note text check (char_length(note) <= 1000),
  checked_on date not null,
  created_at timestamptz not null default now(),
  unique (enrollment_id, day_number)
);
create index challenge_checkins_user_idx on public.challenge_checkins (user_id);

-- ---------------------------------------------------------------------------
-- Row Level Security: owner-only
-- ---------------------------------------------------------------------------
alter table public.challenge_enrollments enable row level security;
alter table public.challenge_checkins enable row level security;

create policy challenge_enrollments_select_own on public.challenge_enrollments
  for select to authenticated using (user_id = (select auth.uid()));
create policy challenge_enrollments_insert_own on public.challenge_enrollments
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy challenge_enrollments_update_own on public.challenge_enrollments
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy challenge_enrollments_delete_own on public.challenge_enrollments
  for delete to authenticated using (user_id = (select auth.uid()));

create policy challenge_checkins_select_own on public.challenge_checkins
  for select to authenticated using (user_id = (select auth.uid()));
create policy challenge_checkins_insert_own on public.challenge_checkins
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.challenge_enrollments e where e.id = enrollment_id and e.user_id = (select auth.uid()))
  );
create policy challenge_checkins_update_own on public.challenge_checkins
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.challenge_enrollments e where e.id = enrollment_id and e.user_id = (select auth.uid()))
  );
create policy challenge_checkins_delete_own on public.challenge_checkins
  for delete to authenticated using (user_id = (select auth.uid()));

-- ===== supabase/migrations/20261017000004_food_barcode.sql =====
-- Barcode scanning: products looked up on Open Food Facts are cached per user in public.foods
-- with source 'openfoodfacts' and source_ref = the product barcode.

alter table public.foods drop constraint if exists foods_source_check;
alter table public.foods
  add constraint foods_source_check check (source in ('custom', 'usda', 'curated', 'openfoodfacts'));

-- Users may cache Open Food Facts products for themselves, like USDA foods.
drop policy if exists foods_insert_own on public.foods;
create policy foods_insert_own on public.foods
  for insert to authenticated with check (
    (owner_id = (select auth.uid()) and source in ('custom', 'usda', 'openfoodfacts'))
    or (owner_id is null and public.is_admin())
  );

-- Cached USDA / Open Food Facts foods are upserted with ON CONFLICT (owner_id, source, source_ref).
-- Postgres can't use a *partial* unique index for that, so the original index made those upserts fail
-- (error 42P10). A plain unique index behaves the same for rows without a source_ref, because
-- NULLs never conflict with each other.
drop index if exists public.foods_owner_source_ref;
create unique index foods_owner_source_ref on public.foods (owner_id, source, source_ref);

-- ===== supabase/migrations/20261017000005_sex_and_diet_type.sql =====
-- Onboarding now asks for sex (used only for calorie estimates) and a diet style.

alter table public.profiles
  add column if not exists sex text check (sex in ('male', 'female', 'unspecified'));
-- Users may update their own sex (column-level grant; role stays non-updatable).
grant update (sex) on public.profiles to authenticated;

alter table public.onboarding_answers
  add column if not exists diet_type text not null default 'balanced' check (diet_type in (
    'balanced', 'high_protein', 'low_carb', 'keto', 'mediterranean', 'paleo', 'vegetarian', 'vegan',
    'pescatarian', 'intermittent_fasting', 'carnivore', 'daniel_fast', 'dash'));

-- ===== supabase/migrations/20261017000006_supplements_and_steps.sql =====
-- Narrow Gate Fitness — supplement stack, supplement check-offs and daily steps.
-- Supplement ids refer to the built-in reference list in the app (src/data/supplements.ts).
-- All rows are private to their owner (no admin access).

create table public.supplement_stack (
  user_id uuid not null references auth.users (id) on delete cascade,
  supplement_id text not null check (char_length(supplement_id) between 1 and 64),
  added_at timestamptz not null default now(),
  primary key (user_id, supplement_id)
);

create table public.supplement_logs (
  user_id uuid not null references auth.users (id) on delete cascade,
  supplement_id text not null check (char_length(supplement_id) between 1 and 64),
  taken_on date not null,
  created_at timestamptz not null default now(),
  primary key (user_id, supplement_id, taken_on)
);
create index supplement_logs_user_day_idx on public.supplement_logs (user_id, taken_on desc);

create table public.daily_steps (
  user_id uuid not null references auth.users (id) on delete cascade,
  day date not null,
  steps integer not null check (steps between 0 and 200000),
  source text not null default 'manual' check (source in ('manual', 'apple_health', 'health_connect')),
  updated_at timestamptz not null default now(),
  primary key (user_id, day)
);
create trigger daily_steps_updated_at before update on public.daily_steps
  for each row execute function public.set_updated_at();

-- Daily step goal (users may update it; column-level grant like the other self-editable profile fields).
alter table public.profiles
  add column if not exists step_goal integer not null default 8000 check (step_goal between 1000 and 50000);
grant update (step_goal) on public.profiles to authenticated;

-- ---------------------------------------------------------------------------
-- Row Level Security: owner-only
-- ---------------------------------------------------------------------------
alter table public.supplement_stack enable row level security;
alter table public.supplement_logs enable row level security;
alter table public.daily_steps enable row level security;

create policy supplement_stack_select_own on public.supplement_stack
  for select to authenticated using (user_id = (select auth.uid()));
create policy supplement_stack_insert_own on public.supplement_stack
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy supplement_stack_update_own on public.supplement_stack
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy supplement_stack_delete_own on public.supplement_stack
  for delete to authenticated using (user_id = (select auth.uid()));

create policy supplement_logs_select_own on public.supplement_logs
  for select to authenticated using (user_id = (select auth.uid()));
create policy supplement_logs_insert_own on public.supplement_logs
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy supplement_logs_update_own on public.supplement_logs
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy supplement_logs_delete_own on public.supplement_logs
  for delete to authenticated using (user_id = (select auth.uid()));

create policy daily_steps_select_own on public.daily_steps
  for select to authenticated using (user_id = (select auth.uid()));
create policy daily_steps_insert_own on public.daily_steps
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy daily_steps_update_own on public.daily_steps
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy daily_steps_delete_own on public.daily_steps
  for delete to authenticated using (user_id = (select auth.uid()));

-- ===== supabase/migrations/20261017000007_onboarding_plan.sql =====
-- Onboarding now builds a calorie budget (MyFitnessPal / MyNetDiary style) alongside the starter program:
-- goal weight, weekly pace and activity level outside workouts. session_minutes and equipment already
-- live on onboarding_answers.
--
-- onboarding_answers is covered by the owner-only RLS policies created in 20261016000002_rls_policies.sql
-- (onboarding_answers_{select,insert,update,delete}_own: user_id = auth.uid()), so the new columns are
-- private to their owner. Columns are nullable so accounts created before this migration keep working;
-- the app falls back to the stored nutrition targets when they are missing.

alter table public.onboarding_answers
  add column if not exists goal_weight_kg numeric(5, 2) check (goal_weight_kg between 25 and 400),
  add column if not exists weekly_change_kg numeric(4, 2) check (weekly_change_kg in (-1, -0.75, -0.5, -0.25, 0, 0.25, 0.5)),
  add column if not exists activity_level text check (activity_level in ('sedentary', 'light', 'active', 'very_active'));

comment on column public.onboarding_answers.goal_weight_kg is 'Optional target bodyweight in kg.';
comment on column public.onboarding_answers.weekly_change_kg is 'Chosen weekly weight change in kg (negative = lose).';
comment on column public.onboarding_answers.activity_level is 'Daily-life activity outside workouts, for the calorie budget.';

-- ===== supabase/migrations/20261019000008_food_amounts.sql =====
-- MyFitnessPal-style amounts for logged food: the exact weight eaten, the unit and quantity picked
-- ("6 oz", "1.5 cup, chopped"), a readable amount ("6 oz (170 g)"), fiber / sugar / sodium, where the
-- values came from, and the nutrition basis (per 100 g, label serving, USDA portions) so an entry can be
-- edited later. All columns are nullable: entries logged before this migration keep working and are
-- edited as "servings" of their own values.
--
-- meal_items already has owner-only RLS for select / insert / update / delete (user_id = auth.uid(),
-- and the parent meal must be the user's own); new columns are covered by those row policies.

alter table public.meal_items
  add column if not exists grams numeric(8, 1) check (grams > 0 and grams <= 20000),
  add column if not exists quantity numeric(10, 3) check (quantity > 0 and quantity <= 100000),
  add column if not exists unit_label text check (char_length(unit_label) between 1 and 100),
  add column if not exists amount_label text check (char_length(amount_label) between 1 and 160),
  add column if not exists fiber_g numeric(6, 1) check (fiber_g >= 0),
  add column if not exists sugar_g numeric(6, 1) check (sugar_g >= 0),
  add column if not exists sodium_mg numeric(9, 1) check (sodium_mg >= 0),
  add column if not exists source text check (source ~ '^(usda:[0-9]{1,10}|off:[0-9]{8,14}|food:[0-9a-f-]{36}|custom)$'),
  add column if not exists basis jsonb check (
    basis is null
    or coalesce(jsonb_typeof(basis) = 'object' and jsonb_typeof(basis -> 'per100') = 'object' and octet_length(basis::text) <= 8000, false)
  );

-- ===== supabase/migrations/20261020000009_ui_prefs.sql =====
-- Display and Faith preferences shown in Profile & Settings (SPEC §1, §12).
--   text_size      : root text scale on top of the system text size.
--   reduce_motion  : turns off page animations and celebration confetti.
--   home_scripture : show the Scripture card on Home (Faith itself is always available).
alter table public.profiles
  add column if not exists text_size text not null default 'default' check (text_size in ('default', 'large', 'xlarge')),
  add column if not exists reduce_motion boolean not null default false,
  add column if not exists home_scripture boolean not null default true;

-- Self-editable like the other profile preferences (column-level grants).
grant update (text_size, reduce_motion, home_scripture) on public.profiles to authenticated;

-- ===== supabase/migrations/20261020000010_activities.sql =====
-- Narrow Gate Fitness — runs and walks ("activities").
--
-- One row per run or walk. The row id is the stable activity id: the client generates it before
-- the first save, so a double-submitted form or a retried upload is a no-op instead of a duplicate,
-- and badges/records derived from activities can key on it.
--
-- Decisions (see docs/RUN_TRACKING_PLAN.md):
-- * distance_m may be null only for a time-only manual entry ("a 30-minute walk"). Treadmill and
--   GPS activities always have a distance. Pace is never stored: it's computed in code from
--   distance_m and moving_s, so there is one source of truth.
-- * moving_s excludes paused time and is never more than elapsed_s. Manual entries default it to
--   elapsed_s when the user doesn't know their moving time.
-- * route is only allowed for GPS activities, so manual/treadmill entries can never carry a route.
-- * Soft delete (deleted_at): reads filter it out; records and badges recalculate from the
--   remaining rows. The owner can also hard-delete (and account deletion cascades).
-- * Duplicate imports: external_id (a wearable/health-app workout id) is unique per user and
--   source, and two live GPS recordings can't start at the same instant.

create table public.activities (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  kind text not null check (kind in ('run', 'walk')),
  source text not null check (source in ('manual', 'treadmill', 'gps')),
  started_at timestamptz not null,
  timezone text not null default 'UTC' check (char_length(timezone) between 1 and 64),
  distance_m numeric(9, 2) check (distance_m is null or (distance_m >= 0 and distance_m <= 500000)),
  elapsed_s integer not null check (elapsed_s between 1 and 172800),
  moving_s integer not null check (moving_s >= 1),
  notes text check (notes is null or char_length(notes) <= 2000),
  perceived_effort smallint check (perceived_effort is null or perceived_effort between 1 and 10),
  route jsonb,
  splits jsonb check (splits is null or jsonb_typeof(splits) = 'array'),
  external_id text check (external_id is null or char_length(external_id) between 1 and 128),
  is_private boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  constraint activities_moving_le_elapsed check (moving_s <= elapsed_s),
  constraint activities_distance_required check (distance_m is not null or source = 'manual'),
  constraint activities_route_gps_only check (route is null or source = 'gps')
);

create index activities_user_started_idx on public.activities (user_id, started_at desc) where deleted_at is null;
create unique index activities_user_source_external_uidx on public.activities (user_id, source, external_id)
  where external_id is not null;
create unique index activities_user_gps_started_uidx on public.activities (user_id, source, started_at)
  where source = 'gps' and deleted_at is null;

create trigger activities_updated_at before update on public.activities
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Row Level Security: owner-only (no admin access; routes are private data)
-- ---------------------------------------------------------------------------
alter table public.activities enable row level security;

create policy activities_select_own on public.activities
  for select to authenticated using (user_id = (select auth.uid()));
create policy activities_insert_own on public.activities
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy activities_update_own on public.activities
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy activities_delete_own on public.activities
  for delete to authenticated using (user_id = (select auth.uid()));

-- ===== supabase/migrations/20261020000011_food_favorites.sql =====
-- Food favorites (SPEC §8 "Favorites and recent foods").
--
-- A favorite points at a food by the same stable source key that meal_items.source uses:
--   usda:<fdcId>      USDA FoodData Central (bundled SR Legacy or the remote API)
--   off:<barcode>     Open Food Facts product
--   food:<uuid>       a row in public.foods (built-in common foods or the user's own saved foods)
-- Hand-entered quick adds ("custom") have no stable identity and can't be favorited.
--
-- name / detail / basis are a display snapshot so the Favorites tab renders without a lookup. When a
-- favorite is logged, nutrition is always re-read on the server from the source (logFoodAction), never
-- taken from this snapshot.
--
-- Rows are private to their owner: owner-only RLS for select / insert / update / delete, no admin
-- access, and they cascade away with the auth user on account deletion.

create table public.food_favorites (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  food_key text not null check (food_key ~ '^(usda:[0-9]{1,10}|off:[0-9]{8,14}|food:[0-9a-f-]{36})$'),
  name text not null check (char_length(name) between 1 and 160),
  detail text check (char_length(detail) <= 200),
  basis jsonb not null check (
    coalesce(jsonb_typeof(basis) = 'object' and jsonb_typeof(basis -> 'per100') = 'object' and octet_length(basis::text) <= 8000, false)
  ),
  is_estimate boolean not null default false,
  created_at timestamptz not null default now(),
  constraint food_favorites_user_key_unique unique (user_id, food_key)
);
create index food_favorites_user_created_idx on public.food_favorites (user_id, created_at desc);

alter table public.food_favorites enable row level security;

create policy food_favorites_select_own on public.food_favorites
  for select to authenticated using (user_id = (select auth.uid()));
create policy food_favorites_insert_own on public.food_favorites
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy food_favorites_update_own on public.food_favorites
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy food_favorites_delete_own on public.food_favorites
  for delete to authenticated using (user_id = (select auth.uid()));

comment on table public.food_favorites is 'Foods a user starred for quick logging. Owner-only.';
comment on column public.food_favorites.food_key is 'Stable source key, same format as meal_items.source (usda:/off:/food:).';

-- ===== supabase/migrations/20261021000012_recipes_planner_grocery.sql =====
-- Narrow Gate Fitness — Stage 2A nutrition: recipes, meal planner, grocery list and day marks (SPEC §8).
--
-- Every table is private to its owner: owner-only RLS for select / insert / update / delete, no admin
-- access, and every row cascades away with the auth user on account deletion. Child rows (recipe
-- ingredients, plan entries, grocery items) also check that the parent row belongs to the same user.
--
-- Deletes are hard deletes, like meals and saved meals: diary entries logged from a recipe or a plan keep
-- their own snapshot of the nutrition (meal_items.basis), so deleting the recipe or plan never changes
-- what was eaten.

-- ---------------------------------------------------------------------------
-- Recipes
-- ---------------------------------------------------------------------------
create table public.recipes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 120),
  servings numeric(6, 2) not null default 1 check (servings > 0 and servings <= 100),
  notes text check (char_length(notes) <= 2000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index recipes_user_idx on public.recipes (user_id, name);
create trigger recipes_updated_at before update on public.recipes
  for each row execute function public.set_updated_at();

-- One row per ingredient. `basis` is a snapshot of the food's nutrition in the same format as
-- meal_items.basis (per 100 g / ml, label serving, USDA household portions, missing macros), taken from the
-- source on the server when the ingredient was added. `quantity` + `unit_label` are the amount picked.
create table public.recipe_ingredients (
  id uuid primary key default gen_random_uuid(),
  recipe_id uuid not null references public.recipes (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  position smallint not null default 0 check (position between 0 and 199),
  name text not null check (char_length(name) between 1 and 160),
  source text not null check (source ~ '^(usda:[0-9]{1,10}|off:[0-9]{8,14}|food:[0-9a-f-]{36})$'),
  quantity numeric(10, 3) not null check (quantity > 0 and quantity <= 100000),
  unit_label text not null check (char_length(unit_label) between 1 and 100),
  grams numeric(8, 1) check (grams > 0 and grams <= 20000),
  amount_label text check (char_length(amount_label) between 1 and 160),
  basis jsonb not null check (
    coalesce(jsonb_typeof(basis) = 'object' and jsonb_typeof(basis -> 'per100') = 'object' and octet_length(basis::text) <= 8000, false)
  ),
  is_estimate boolean not null default false,
  created_at timestamptz not null default now()
);
create index recipe_ingredients_recipe_idx on public.recipe_ingredients (recipe_id, position);

-- Diary entries logged from a recipe or a built-in planner recipe point back at it.
alter table public.meal_items drop constraint if exists meal_items_source_check;
alter table public.meal_items add constraint meal_items_source_check
  check (source ~ '^(usda:[0-9]{1,10}|off:[0-9]{8,14}|food:[0-9a-f-]{36}|recipe:[0-9a-f-]{36}|app:[a-z0-9-]{1,60}|custom)$');

-- ---------------------------------------------------------------------------
-- Meal planner
-- ---------------------------------------------------------------------------
create table public.meal_plan_settings (
  user_id uuid primary key references auth.users (id) on delete cascade,
  meals_per_day smallint not null default 3 check (meals_per_day between 2 and 5),
  budget text not null default 'any' check (budget in ('low', 'medium', 'any')),
  allergies text[] not null default '{}' check (cardinality(allergies) <= 20 and octet_length(array_to_string(allergies, ',')) <= 1000),
  dislikes text[] not null default '{}' check (cardinality(dislikes) <= 20 and octet_length(array_to_string(dislikes, ',')) <= 1000),
  include_app_recipes boolean not null default true,
  updated_at timestamptz not null default now()
);
create trigger meal_plan_settings_updated_at before update on public.meal_plan_settings
  for each row execute function public.set_updated_at();

-- A generated plan for a run of days. `targets` and `settings` are snapshots of what it was built for.
create table public.meal_plans (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  start_date date not null,
  days smallint not null default 7 check (days between 1 and 14),
  targets jsonb not null check (jsonb_typeof(targets) = 'object' and octet_length(targets::text) <= 2000),
  settings jsonb not null check (jsonb_typeof(settings) = 'object' and octet_length(settings::text) <= 4000),
  created_at timestamptz not null default now(),
  constraint meal_plans_user_start_unique unique (user_id, start_date)
);

-- One planned meal. Planned meals are separate from what was eaten: "Log this meal" copies it into the
-- diary (meals / meal_items) and records logged_at here.
create table public.meal_plan_entries (
  id uuid primary key default gen_random_uuid(),
  plan_id uuid not null references public.meal_plans (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  plan_date date not null,
  slot smallint not null check (slot between 0 and 4),
  meal_type text not null check (meal_type in ('breakfast', 'lunch', 'dinner', 'snack')),
  label text not null check (char_length(label) between 1 and 40),
  source_key text not null check (source_key ~ '^(app:[a-z0-9-]{1,60}|recipe:[0-9a-f-]{36}|meal:[0-9a-f-]{36})$'),
  name text not null check (char_length(name) between 1 and 160),
  portion numeric(4, 2) not null check (portion >= 0.25 and portion <= 4),
  -- Nutrition for ONE serving at planning time, plus whether every ingredient had data.
  per_serving jsonb not null check (jsonb_typeof(per_serving) = 'object' and octet_length(per_serving::text) <= 2000),
  -- Ingredient amounts for ONE serving, for the grocery list: [{key, name, quantity, unitLabel}].
  ingredients jsonb not null default '[]' check (jsonb_typeof(ingredients) = 'array' and octet_length(ingredients::text) <= 20000),
  logged_at timestamptz,
  created_at timestamptz not null default now(),
  constraint meal_plan_entries_slot_unique unique (plan_id, plan_date, slot)
);
create index meal_plan_entries_user_date_idx on public.meal_plan_entries (user_id, plan_date);

-- ---------------------------------------------------------------------------
-- Grocery list (one per user)
-- ---------------------------------------------------------------------------
create table public.grocery_lists (
  user_id uuid primary key references auth.users (id) on delete cascade,
  from_date date,
  to_date date,
  generated_at timestamptz,
  updated_at timestamptz not null default now(),
  check (from_date is null or to_date is null or from_date <= to_date)
);
create trigger grocery_lists_updated_at before update on public.grocery_lists
  for each row execute function public.set_updated_at();

create table public.grocery_items (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 160),
  quantity numeric(10, 2) check (quantity is null or (quantity > 0 and quantity <= 100000)),
  unit text check (char_length(unit) between 1 and 60),
  note text check (char_length(note) <= 300),
  origin text not null check (origin in ('plan', 'manual')),
  ingredient_key text check (char_length(ingredient_key) <= 80),
  checked boolean not null default false,
  position integer not null default 0,
  created_at timestamptz not null default now()
);
create index grocery_items_user_idx on public.grocery_items (user_id, position);

-- ---------------------------------------------------------------------------
-- Day marks: "this day is complete" or "I ate nothing" (a fast), so weekly summaries can tell a day
-- logged as zero from a day that simply wasn't logged.
-- ---------------------------------------------------------------------------
create table public.nutrition_day_marks (
  user_id uuid not null references auth.users (id) on delete cascade,
  day date not null,
  status text not null check (status in ('complete', 'fasted')),
  updated_at timestamptz not null default now(),
  primary key (user_id, day)
);
create trigger nutrition_day_marks_updated_at before update on public.nutrition_day_marks
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Row Level Security: owner-only
-- ---------------------------------------------------------------------------
alter table public.recipes enable row level security;
alter table public.recipe_ingredients enable row level security;
alter table public.meal_plan_settings enable row level security;
alter table public.meal_plans enable row level security;
alter table public.meal_plan_entries enable row level security;
alter table public.grocery_lists enable row level security;
alter table public.grocery_items enable row level security;
alter table public.nutrition_day_marks enable row level security;

do $$
declare t text;
begin
  foreach t in array array['recipes', 'meal_plan_settings', 'meal_plans', 'grocery_lists', 'grocery_items', 'nutrition_day_marks'] loop
    execute format('create policy %1$s_select_own on public.%1$s for select to authenticated using (user_id = (select auth.uid()))', t);
    execute format('create policy %1$s_insert_own on public.%1$s for insert to authenticated with check (user_id = (select auth.uid()))', t);
    execute format('create policy %1$s_update_own on public.%1$s for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()))', t);
    execute format('create policy %1$s_delete_own on public.%1$s for delete to authenticated using (user_id = (select auth.uid()))', t);
  end loop;
end $$;

-- Children: the row and its parent must both be the user's own.
create policy recipe_ingredients_select_own on public.recipe_ingredients
  for select to authenticated using (user_id = (select auth.uid()));
create policy recipe_ingredients_insert_own on public.recipe_ingredients
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.recipes r where r.id = recipe_id and r.user_id = (select auth.uid()))
  );
create policy recipe_ingredients_update_own on public.recipe_ingredients
  for update to authenticated using (user_id = (select auth.uid())) with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.recipes r where r.id = recipe_id and r.user_id = (select auth.uid()))
  );
create policy recipe_ingredients_delete_own on public.recipe_ingredients
  for delete to authenticated using (user_id = (select auth.uid()));

create policy meal_plan_entries_select_own on public.meal_plan_entries
  for select to authenticated using (user_id = (select auth.uid()));
create policy meal_plan_entries_insert_own on public.meal_plan_entries
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.meal_plans p where p.id = plan_id and p.user_id = (select auth.uid()))
  );
create policy meal_plan_entries_update_own on public.meal_plan_entries
  for update to authenticated using (user_id = (select auth.uid())) with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.meal_plans p where p.id = plan_id and p.user_id = (select auth.uid()))
  );
create policy meal_plan_entries_delete_own on public.meal_plan_entries
  for delete to authenticated using (user_id = (select auth.uid()));

comment on table public.recipes is 'User recipes (ingredients in recipe_ingredients). Owner-only.';
comment on table public.recipe_ingredients is 'Recipe ingredients with a nutrition basis snapshot. Owner-only.';
comment on table public.meal_plan_settings is 'Meal planner preferences: meals per day, budget, allergies, dislikes. Owner-only.';
comment on table public.meal_plans is 'Generated meal plans. Owner-only.';
comment on table public.meal_plan_entries is 'Planned meals (separate from the diary until logged). Owner-only.';
comment on table public.grocery_lists is 'The date range the grocery list was generated for. Owner-only.';
comment on table public.grocery_items is 'Grocery list lines (from the plan or added by hand). Owner-only.';
comment on table public.nutrition_day_marks is 'Days marked complete or as a fast (logged as zero). Owner-only.';

-- ===== supabase/migrations/20261021000013_training_templates.sql =====
-- Narrow Gate Fitness — Stage 2B training (SPEC §5, §6).
--
--   * training_programs.needs_specialist_review: specialist programming (show prep, meet prep, combat, active
--     aging) that a qualified coach has not reviewed yet. The app shows "Not yet reviewed by a qualified coach".
--   * profiles.rest_timer_sound / rest_timer_vibrate: optional rest-timer alerts in the workout logger.
--   * workout_templates + workout_template_exercises: saved custom workouts (order, sets, reps / time /
--     distance, rest, supersets). Private to their owner, cascade on account deletion, included in the export.

alter table public.training_programs
  add column if not exists needs_specialist_review boolean not null default false;

alter table public.profiles
  add column if not exists rest_timer_sound boolean not null default true,
  add column if not exists rest_timer_vibrate boolean not null default true;
grant update (rest_timer_sound, rest_timer_vibrate) on public.profiles to authenticated;

create table public.workout_templates (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  name text not null check (char_length(name) between 1 and 120),
  notes text check (char_length(notes) <= 2000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index workout_templates_user_idx on public.workout_templates (user_id, updated_at desc);
create trigger workout_templates_updated_at before update on public.workout_templates
  for each row execute function public.set_updated_at();

-- One row per exercise, in order. `target` says what each set prescribes: reps, a time or a distance.
-- Exercises sharing a `superset_group` (1–20) within a template are done as a superset: one set of each in
-- turn, with rest only after the round.
create table public.workout_template_exercises (
  id uuid primary key default gen_random_uuid(),
  template_id uuid not null references public.workout_templates (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  exercise_id uuid not null references public.exercises (id) on delete restrict,
  position smallint not null check (position between 0 and 39),
  sets smallint not null check (sets between 1 and 20),
  target text not null default 'reps' check (target in ('reps', 'time', 'distance')),
  reps text check (char_length(reps) between 1 and 20),
  duration_seconds integer check (duration_seconds between 5 and 7200),
  distance_m numeric(8, 1) check (distance_m > 0 and distance_m <= 100000),
  rest_seconds smallint not null default 90 check (rest_seconds between 0 and 900),
  superset_group smallint check (superset_group between 1 and 20),
  notes text check (char_length(notes) <= 500),
  unique (template_id, position),
  check (
    (target = 'reps' and reps is not null)
    or (target = 'time' and duration_seconds is not null)
    or (target = 'distance' and distance_m is not null)
  )
);
create index workout_template_exercises_template_idx on public.workout_template_exercises (template_id, position);
create index workout_template_exercises_exercise_idx on public.workout_template_exercises (exercise_id);

alter table public.workout_templates enable row level security;
alter table public.workout_template_exercises enable row level security;

create policy workout_templates_select_own on public.workout_templates
  for select to authenticated using (user_id = (select auth.uid()));
create policy workout_templates_insert_own on public.workout_templates
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy workout_templates_update_own on public.workout_templates
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy workout_templates_delete_own on public.workout_templates
  for delete to authenticated using (user_id = (select auth.uid()));

-- Children: the row and its parent template must both be the user's own.
create policy workout_template_exercises_select_own on public.workout_template_exercises
  for select to authenticated using (user_id = (select auth.uid()));
create policy workout_template_exercises_insert_own on public.workout_template_exercises
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.workout_templates t where t.id = template_id and t.user_id = (select auth.uid()))
  );
create policy workout_template_exercises_update_own on public.workout_template_exercises
  for update to authenticated using (user_id = (select auth.uid())) with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.workout_templates t where t.id = template_id and t.user_id = (select auth.uid()))
  );
create policy workout_template_exercises_delete_own on public.workout_template_exercises
  for delete to authenticated using (user_id = (select auth.uid()));

grant select, insert, update, delete on public.workout_templates, public.workout_template_exercises to authenticated;

-- ===== supabase/migrations/20261021000020_faith_calendar.sql =====
-- Narrow Gate Fitness — Stage 2C: prayer journal, daily practices, faith reminders, secondary goal and
-- training-calendar reschedules (SPEC §3, §4, §12).
--
-- Every new table is private to its owner: owner-only RLS for select / insert / update / delete, no admin
-- access, and rows cascade away with the auth user on account deletion.

-- ---------------------------------------------------------------------------
-- Prayer journal: entry type, answered prayers and the AI-coach opt-in.
-- ---------------------------------------------------------------------------
-- kind: 'reflection' (general), 'request' (a prayer request) or 'praise' (praise / thanksgiving).
-- A request can be marked answered (answered_on + optional note).
-- share_with_coach is OFF by default: the AI coach only ever sees entries the user ticked.
alter table public.faith_journal_entries
  add column kind text not null default 'reflection' check (kind in ('reflection', 'request', 'praise')),
  add column answered_on date,
  add column answered_note text check (char_length(answered_note) <= 2000),
  add column share_with_coach boolean not null default false,
  add constraint faith_journal_answered_note_needs_date check (answered_note is null or answered_on is not null);

create index faith_journal_user_kind_idx on public.faith_journal_entries (user_id, kind, entry_date desc);

-- ---------------------------------------------------------------------------
-- Daily practices reuse discipline_goals / discipline_checkins. `practice` names the preset
-- (Scripture reading, prayer, gratitude, fasting, worship, rest/Sabbath) or 'custom'.
-- ---------------------------------------------------------------------------
alter table public.discipline_goals
  add column practice text not null default 'custom'
    check (practice in ('scripture', 'prayer', 'gratitude', 'fasting', 'worship', 'rest', 'custom'));

-- One active row per preset practice (custom practices can repeat).
create unique index discipline_goals_one_preset_idx on public.discipline_goals (user_id, practice)
  where practice <> 'custom' and is_active;

-- ---------------------------------------------------------------------------
-- Faith reminders: optional, off by default (no row = off). Delivered as local notifications by the
-- iPhone / Android app; the web app only stores the settings.
-- ---------------------------------------------------------------------------
create table public.faith_reminders (
  user_id uuid not null references auth.users (id) on delete cascade,
  kind text not null check (kind in ('devotional', 'prayer', 'practices')),
  enabled boolean not null default false,
  remind_at time not null default '07:00',
  -- JavaScript weekdays: 0 = Sunday … 6 = Saturday.
  weekdays smallint[] not null default '{0,1,2,3,4,5,6}'
    check (cardinality(weekdays) <= 7 and weekdays <@ array[0, 1, 2, 3, 4, 5, 6]::smallint[]),
  updated_at timestamptz not null default now(),
  primary key (user_id, kind)
);
create trigger faith_reminders_updated_at before update on public.faith_reminders
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Secondary goal (optional, onboarding).
-- ---------------------------------------------------------------------------
alter table public.onboarding_answers
  add column secondary_goal text check (secondary_goal in (
    'build_strength', 'build_muscle', 'lose_fat', 'improve_conditioning', 'athletic_performance',
    'combat_sports', 'general_health', 'mobility', 'run_5k'
  ));

-- ---------------------------------------------------------------------------
-- Training calendar: a planned program session moved to another date. Keyed by the enrolment and the
-- program day, so completed workouts (workout_sessions) are never touched by a reschedule.
-- ---------------------------------------------------------------------------
create table public.planned_session_overrides (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  user_program_id uuid not null references public.user_programs (id) on delete cascade,
  program_day_id uuid not null references public.program_days (id) on delete cascade,
  planned_date date not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint planned_session_overrides_unique unique (user_program_id, program_day_id)
);
create index planned_session_overrides_user_idx on public.planned_session_overrides (user_id, planned_date);
create trigger planned_session_overrides_updated_at before update on public.planned_session_overrides
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Row Level Security: owner-only
-- ---------------------------------------------------------------------------
alter table public.faith_reminders enable row level security;
alter table public.planned_session_overrides enable row level security;

create policy faith_reminders_select_own on public.faith_reminders
  for select to authenticated using (user_id = (select auth.uid()));
create policy faith_reminders_insert_own on public.faith_reminders
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy faith_reminders_update_own on public.faith_reminders
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy faith_reminders_delete_own on public.faith_reminders
  for delete to authenticated using (user_id = (select auth.uid()));

-- The row and the enrolment it reschedules must both be the user's own.
create policy planned_session_overrides_select_own on public.planned_session_overrides
  for select to authenticated using (user_id = (select auth.uid()));
create policy planned_session_overrides_insert_own on public.planned_session_overrides
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.user_programs up where up.id = user_program_id and up.user_id = (select auth.uid()))
  );
create policy planned_session_overrides_update_own on public.planned_session_overrides
  for update to authenticated using (user_id = (select auth.uid())) with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.user_programs up where up.id = user_program_id and up.user_id = (select auth.uid()))
  );
create policy planned_session_overrides_delete_own on public.planned_session_overrides
  for delete to authenticated using (user_id = (select auth.uid()));

comment on table public.faith_reminders is 'Optional devotional / prayer / practice reminder settings (off by default). Owner-only.';
comment on table public.planned_session_overrides is 'Planned program sessions moved to another date on the training calendar. Owner-only.';
comment on column public.faith_journal_entries.share_with_coach is 'Off by default. Only entries with this set are ever included in the AI coach context.';

-- ===== supabase/migrations/20261022000021_memberships_stage1.sql =====
-- Narrow Gate Fitness — AI model routing (memberships stage 1).
--
-- Pro coaching runs most requests on a fast model and sends plan generation and complex coaching questions to a
-- larger model, capped at a monthly share. Each usage row now records which model served it so the cap can be
-- enforced and costs reviewed. Rows written before routing existed count as the fast tier.
-- Users still can't write their own usage rows (service role only), so the cap can't be bypassed from the client.
alter table public.ai_usage_events
  add column model text check (char_length(model) <= 100),
  add column model_tier text not null default 'fast' check (model_tier in ('fast', 'smart'));

create index ai_usage_events_user_tier_idx on public.ai_usage_events (user_id, model_tier, created_at desc);

-- AI data-sharing consent. The AI coach sends parts of the user's own data to the AI provider (Anthropic) to
-- answer. Nothing is sent until the user allows it on the coach screen; they can withdraw it any time in
-- Profile & Settings, which stops the coach until they allow it again (App Store guideline 5.1.2(i)).
alter table public.profiles add column ai_data_consent_at timestamptz;
grant update (ai_data_consent_at) on public.profiles to authenticated;

-- ===== supabase/migrations/20261022000022_legacy_plan_terms.sql =====
-- Narrow Gate Fitness — keep existing subscribers' AI allowance through the October 2026 plan change.
--
-- Before this change Plus included an AI coach allowance (60 messages a month) and Pro 400 messages and 20 plan
-- generations. Under the new plans Plus has no AI and Pro has 150 messages. So nobody who is already paying loses
-- anything unexpectedly, every Stripe subscription that exists when this migration runs keeps its previous AI
-- allowance for as long as that subscription stays on the same plan and keeps access. Subscriptions created
-- afterwards follow the new plans. If there are no existing subscriptions, nothing is inserted.
--
-- Nothing in `subscriptions` or `user_entitlements` is changed. The terms end on their own when the subscription
-- ends (cancelled and past its paid period, or expired). The owner can end them earlier with notice by setting
-- `ends_at`. The allowances below are the previous code defaults; if production overrode them with
-- PLAN_PLUS_AI_MONTHLY_LIMIT / PLAN_PRO_AI_MONTHLY_LIMIT, update these rows to match.
create table public.legacy_plan_terms (
  stripe_subscription_id text primary key references public.subscriptions (stripe_subscription_id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  plan text not null check (plan in ('plus', 'pro')),
  ai_monthly_limit integer not null check (ai_monthly_limit >= 0),
  ai_plan_monthly_limit integer not null check (ai_plan_monthly_limit >= 0),
  ai_smart_monthly_limit integer not null check (ai_smart_monthly_limit >= 0),
  ends_at timestamptz,
  reason text not null default 'Subscribed before the October 2026 plan change' check (char_length(reason) <= 200),
  created_at timestamptz not null default now()
);
create index legacy_plan_terms_user_idx on public.legacy_plan_terms (user_id);

alter table public.legacy_plan_terms enable row level security;
-- Members can see their own kept terms (shown on Plans & billing); only the service role writes.
create policy legacy_plan_terms_select_own on public.legacy_plan_terms
  for select to authenticated using (user_id = (select auth.uid()));

-- One-time snapshot: every subscription that has, or can still regain, access when this migration runs.
-- (Run once here, not kept as a callable function, so later subscriptions can't be added to it by mistake.)
select s.stripe_subscription_id, s.user_id, s.plan,
       case s.plan when 'plus' then 60 else 400 end,
       case s.plan when 'plus' then 0 else 20 end,
       case s.plan when 'plus' then 6 else 40 end
from public.subscriptions s
where s.status in ('active', 'trialing', 'past_due', 'unpaid', 'paused')
   or (s.status = 'canceled' and s.current_period_end > now())
on conflict (stripe_subscription_id) do nothing;

-- ===== supabase/migrations/20261022000023_store_subscriptions.sql =====
-- Narrow Gate Fitness — App Store / Google Play subscriptions through RevenueCat (stage 2).
--
-- RevenueCat is the source of truth for in-app purchases. After every RevenueCat webhook (and after a purchase or
-- "Restore purchases" in the app) the server fetches the customer's current state from RevenueCat's REST API and
-- stores one row per store product here. Entitlements are then recomputed from these rows together with the
-- Stripe rows in `subscriptions`, so a member who pays on both gets the higher plan. Only the service role writes.
create table public.store_subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  store text not null check (store in ('app_store', 'play_store', 'test_store', 'other')),
  product_id text not null check (char_length(product_id) <= 200),
  -- The plan this product grants (from the RevenueCat entitlement it unlocks). Null if it isn't attached to one.
  plan text check (plan in ('plus', 'pro')),
  period_type text check (char_length(period_type) <= 20),
  purchased_at timestamptz,
  original_purchased_at timestamptz,
  expires_at timestamptz,
  grace_period_expires_at timestamptz,
  unsubscribe_detected_at timestamptz,
  billing_issue_detected_at timestamptz,
  refunded_at timestamptz,
  is_sandbox boolean not null default false,
  ownership_type text check (char_length(ownership_type) <= 30),
  store_transaction_id text check (char_length(store_transaction_id) <= 200),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, store, product_id)
);
create index store_subscriptions_user_idx on public.store_subscriptions (user_id);
create trigger store_subscriptions_updated_at before update on public.store_subscriptions
  for each row execute function public.set_updated_at();

alter table public.store_subscriptions enable row level security;
create policy store_subscriptions_select_own on public.store_subscriptions
  for select to authenticated using (user_id = (select auth.uid()));

-- Webhook deliveries already processed (RevenueCat retries with the same event id). No personal data is kept.
create table public.revenuecat_events (
  id text primary key check (char_length(id) <= 200),
  type text not null check (char_length(type) <= 60),
  environment text check (char_length(environment) <= 20),
  processed_at timestamptz not null default now()
);
alter table public.revenuecat_events enable row level security;
-- revenuecat_events: no policies — service role only.

-- Entitlements can now come from the stores as well as Stripe and admin grants.
alter table public.user_entitlements drop constraint user_entitlements_source_check;
alter table public.user_entitlements
  add constraint user_entitlements_source_check check (source in ('default', 'stripe', 'admin', 'app_store', 'play_store'));

-- ===== supabase/migrations/20261023000024_plan_enforcement.sql =====
-- Narrow Gate Fitness — enforce paid features in the database as well as in the server actions.
--
-- The Supabase anon key is public, so a signed-in member can call the REST API with their own session and skip the
-- server actions. Row level security already kept every member to their own rows, but it didn't check the plan, so
-- a Free member could create recipes, meal plans and grocery lists, build custom or AI programs, save more than five
-- workouts, move calendar sessions, enrol in Plus programs and read their prescriptions. These policies add the plan
-- check. Nothing existing is changed or removed: they only govern new writes (and reads of paid prescriptions), so
-- a member who downgrades keeps everything they made.

-- The member's current plan: their entitlement while it's valid, otherwise Free (the same rule as getUserPlan in
-- src/server/auth.ts). Anonymous visitors are Free.
create or replace function public.plan_of(p_user_id uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select e.plan from public.user_entitlements e
      where e.user_id = p_user_id and (e.valid_until is null or e.valid_until > now())),
    'free');
$$;

create or replace function public.plan_rank(p_plan text)
returns integer
language sql
immutable
as $$
  select case p_plan when 'pro' then 2 when 'plus' then 1 else 0 end;
$$;

-- Does the signed-in member's plan include `p_min_plan`?
create or replace function public.has_plan(p_min_plan text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.plan_rank(public.plan_of(auth.uid())) >= public.plan_rank(p_min_plan);
$$;

-- Can the signed-in member use this program's prescriptions: their own program, a published program at their
-- plan's tier or below, or as an admin.
create or replace function public.can_use_program(p_program_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.training_programs p
    where p.id = p_program_id
      and (p.owner_id = auth.uid() or public.is_admin() or (p.is_published and public.has_plan(p.tier)))
  );
$$;

revoke all on function public.plan_of(uuid) from public, anon, authenticated;
grant execute on function public.plan_of(uuid) to authenticated, service_role;

-- Program prescriptions (sets, reps, rest) of paid programs: only for members whose plan includes them. Week and
-- day names stay readable, as the program page shows them as a preview.
drop policy if exists program_exercises_read on public.program_exercises;
create policy program_exercises_read on public.program_exercises
  for select to anon, authenticated using (public.can_use_program(public.program_of_day(day_id)));

-- Enrolling in a program needs a plan that includes it.
drop policy if exists user_programs_visible_program on public.user_programs;
create policy user_programs_visible_program on public.user_programs
  as restrictive for insert to authenticated with check (public.can_use_program(program_id));

-- Private programs: starter programs (built at sign-up) for everyone, custom programs with Plus, AI programs with Pro.
drop policy if exists training_programs_insert on public.training_programs;
create policy training_programs_insert on public.training_programs
  for insert to authenticated with check (
    (
      owner_id = (select auth.uid()) and is_published = false
      and (
        source = 'starter'
        or (source = 'custom' and public.has_plan('plus'))
        or (source = 'ai' and public.has_plan('pro'))
      )
    )
    or (owner_id is null and public.is_admin())
  );

-- Recipes, the meal planner and grocery lists (Plus): creating new rows needs the plan.
do $$
declare
  t text;
begin
  foreach t in array array[
    'recipes', 'recipe_ingredients', 'meal_plan_settings', 'meal_plans', 'meal_plan_entries', 'grocery_lists', 'grocery_items'
  ] loop
    execute format('create policy %I on public.%I as restrictive for insert to authenticated with check (public.has_plan(''plus''))', t || '_plan', t);
  end loop;
end;
$$;

-- Moving a session on the calendar (Plus). Moving it back (deleting the override) stays open to everyone.
create policy planned_session_overrides_plan_insert on public.planned_session_overrides
  as restrictive for insert to authenticated with check (public.has_plan('plus'));
create policy planned_session_overrides_plan_update on public.planned_session_overrides
  as restrictive for update to authenticated using (public.has_plan('plus')) with check (public.has_plan('plus'));

-- Saved workouts: five on Free (PLAN_FREE_TEMPLATE_LIMIT's default in src/lib/domain/plans.ts; keep them equal).
-- A trigger rather than a policy, so two saves at the same moment can't both slip under the limit: it takes a
-- per-member lock before counting.
create or replace function public.enforce_free_template_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform pg_advisory_xact_lock(hashtextextended('workout_templates:' || new.user_id::text, 0));
  if public.plan_rank(public.plan_of(new.user_id)) = 0
     and (select count(*) from public.workout_templates where user_id = new.user_id) >= 5 then
    raise exception 'Free plan limit: 5 saved workouts' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create trigger workout_templates_free_limit before insert on public.workout_templates
  for each row execute function public.enforce_free_template_limit();

-- ===== supabase/migrations/20261023000025_ai_usage_reservation.sql =====
-- Narrow Gate Fitness — make the AI coach's limits exact and impossible to sidestep.
--
-- Before: usage was recorded after the reply was saved, so (a) several requests sent at once could all pass the
-- check before any was counted, and (b) a request whose reply failed to save (for example because the member
-- deleted the conversation mid-reply) was never counted, though the member had already seen the streamed text.
-- Now the server reserves a usage row before calling the AI provider, under a per-member lock that re-checks every
-- limit, and fills in the model and token counts afterwards. A reservation is removed only if the provider call
-- itself fails, so members aren't charged for errors.

create or replace function public.reserve_ai_usage(
  p_user_id uuid,
  p_kind text,
  p_tier text,
  p_chat_limit integer,
  p_plan_limit integer,
  p_smart_limit integer,
  p_per_minute integer
)
returns table (usage_id uuid, model_tier text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_month timestamptz := date_trunc('month', now() at time zone 'utc') at time zone 'utc';
  v_total integer;
  v_plans integer;
  v_smart integer;
  v_recent integer;
  v_tier text := p_tier;
begin
  perform pg_advisory_xact_lock(hashtextextended('ai_usage:' || p_user_id::text, 0));
  select count(*), count(*) filter (where e.kind = 'plan'), count(*) filter (where e.model_tier = 'smart')
    into v_total, v_plans, v_smart
    from public.ai_usage_events e where e.user_id = p_user_id and e.created_at >= v_month;
  select count(*) into v_recent from public.ai_usage_events e where e.user_id = p_user_id and e.created_at >= now() - interval '60 seconds';
  if v_recent >= p_per_minute then
    raise exception 'ai_rate_limited' using errcode = 'P0001';
  end if;
  if v_total >= p_chat_limit then
    raise exception 'ai_quota' using errcode = 'P0001';
  end if;
  if p_kind = 'plan' and (v_plans >= p_plan_limit or v_smart >= p_smart_limit) then
    raise exception 'ai_quota_plan' using errcode = 'P0001';
  end if;
  -- A chat that would have used the larger model falls back to the fast one once that share is used up.
  if v_tier = 'smart' and v_smart >= p_smart_limit then
    v_tier := 'fast';
  end if;
    values (p_user_id, p_kind, v_tier)
    returning id into usage_id;
  model_tier := v_tier;
  return next;
end;
$$;
revoke all on function public.reserve_ai_usage(uuid, text, text, integer, integer, integer, integer) from public, anon, authenticated;
grant execute on function public.reserve_ai_usage(uuid, text, text, integer, integer, integer, integer) to service_role;

-- Coach messages: members write only their own questions (replies are written by the server), and can only change
-- a suggestion's status, not any message's text. This stops a member planting long fake "assistant" turns that
-- would be sent to the AI as history.
drop policy if exists ai_messages_insert_own on public.ai_messages;
create policy ai_messages_insert_own on public.ai_messages
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and role = 'user'
    and exists (select 1 from public.ai_conversations c where c.id = conversation_id and c.user_id = (select auth.uid()))
  );
revoke update on public.ai_messages from authenticated;
grant update (proposal_status) on public.ai_messages to authenticated;

-- ===== supabase/migrations/20261024000026_coach_memory.sql =====
-- Narrow Gate Fitness — long-term AI coaching memory (Pro).
--
-- Memories are short notes the coach keeps about a member across conversations and devices: a secondary goal, an
-- exercise they prefer, when they train, how they like to be coached, a change they approved. They hold only what
-- the structured data doesn't (goal, experience, equipment, program, logs and targets stay in their own tables and
-- are read fresh every turn). Nothing is saved without the member: memory is off until they turn it on, the coach
-- can only suggest a memory (the member saves, edits or declines it), and every memory can be viewed, edited and
-- deleted. Deleting the account removes them (on delete cascade).

-- Does the signed-in member have the AI coach: Pro, or a subscription that kept its AI allowance from before the
-- October 2026 plan change (the same rule as aiAllowance / legacyTermsApply in src/lib/domain/plans.ts).
create or replace function public.has_ai_coach()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.has_plan('pro') or exists (
    select 1
    from public.legacy_plan_terms t
    join public.subscriptions s on s.stripe_subscription_id = t.stripe_subscription_id
    where t.user_id = auth.uid()
      and t.ai_monthly_limit > 0
      and (t.ends_at is null or t.ends_at > now())
      and s.plan = t.plan
      and s.status in ('active', 'trialing', 'past_due')
      and (s.current_period_end is null or s.current_period_end > now())
  );
$$;
revoke all on function public.has_ai_coach() from public, anon;
grant execute on function public.has_ai_coach() to authenticated, service_role;

-- The member's switch (off by default; turning it on is their consent) and when they agreed.
alter table public.profiles
  add column coach_memory_enabled boolean not null default false,
  add column coach_memory_consent_at timestamptz;
grant update (coach_memory_enabled, coach_memory_consent_at) on public.profiles to authenticated;

-- "Don't remember anything from this chat."
alter table public.ai_conversations add column memory_off boolean not null default false;

create table public.coach_memories (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  category text not null check (category in (
    'goals', 'experience', 'exercise_preferences', 'equipment', 'schedule', 'nutrition',
    'training_changes', 'recovery', 'milestones', 'coaching_style', 'other'
  )),
  content text not null check (char_length(content) between 3 and 300),
  -- coach: suggested by the coach and saved by the member; member: added on the memory screen;
  -- approved_change: recorded when the member confirmed a coach-suggested change.
  source text not null default 'member' check (source in ('coach', 'member', 'approved_change')),
  source_message_id uuid references public.ai_messages (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index coach_memories_user_idx on public.coach_memories (user_id, created_at desc);
create trigger coach_memories_updated_at before update on public.coach_memories
  for each row execute function public.set_updated_at();

alter table public.coach_memories enable row level security;

-- Members always see and can delete their own memories (also after a downgrade or with memory switched off).
create policy coach_memories_select_own on public.coach_memories
  for select to authenticated using (user_id = (select auth.uid()));
create policy coach_memories_delete_own on public.coach_memories
  for delete to authenticated using (user_id = (select auth.uid()));
-- Adding or editing needs the AI coach and memory switched on.
create policy coach_memories_insert_own on public.coach_memories
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and public.has_ai_coach()
    and exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.coach_memory_enabled)
  );
create policy coach_memories_update_own on public.coach_memories
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (
    user_id = (select auth.uid())
    and public.has_ai_coach()
    and exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.coach_memory_enabled)
  );
revoke update on public.coach_memories from authenticated;
grant update (category, content) on public.coach_memories to authenticated;

-- At most 100 memories per member (MEMORY_LIMIT in src/lib/coach/memory.ts; keep them equal). Locked per member so
-- two saves at once can't both slip under the limit.
create or replace function public.enforce_coach_memory_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform pg_advisory_xact_lock(hashtextextended('coach_memories:' || new.user_id::text, 0));
  if (select count(*) from public.coach_memories where user_id = new.user_id) >= 100 then
    raise exception 'coach_memory_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create trigger coach_memories_limit before insert on public.coach_memories
  for each row execute function public.enforce_coach_memory_limit();

-- ===== supabase/migrations/20261024000027_adaptive_training.sql =====
-- Narrow Gate Fitness — adaptive training and recovery (Pro).
--
-- The training review (and the AI coach) suggest changes from the member's logs: a target load for the next
-- session, a recovery week, one more or one fewer set. Nothing changes unless the member accepts, and every accepted
-- change is recorded with what it replaced, so it can be reviewed and undone. Workout history is never touched.

-- Approved target loads, shown in the workout logger beside "Last time".
create table public.exercise_targets (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  exercise_id uuid not null references public.exercises (id) on delete cascade,
  weight_kg numeric(6, 2) check (weight_kg > 0 and weight_kg <= 1000),
  reps smallint check (reps between 1 and 100),
  note text check (char_length(note) <= 300),
  source text not null check (source in ('review', 'coach')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, exercise_id)
);
create trigger exercise_targets_updated_at before update on public.exercise_targets
  for each row execute function public.set_updated_at();

-- Every accepted change, with the values it replaced (for review and undo).
create table public.training_adjustments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  program_id uuid references public.training_programs (id) on delete cascade,
  kind text not null check (kind in ('exercise_target', 'deload_week', 'volume_change')),
  summary text not null check (char_length(summary) <= 300),
  reason text check (char_length(reason) <= 1000),
  -- [{ "table": "program_exercises" | "program_weeks" | "exercise_targets", "id": uuid, "before": {...}, "after": {...} }]
  changes jsonb not null default '[]',
  source text not null check (source in ('review', 'coach')),
  recommendation_key text check (char_length(recommendation_key) <= 200),
  source_message_id uuid references public.ai_messages (id) on delete set null,
  created_at timestamptz not null default now(),
  reverted_at timestamptz
);
create index training_adjustments_user_idx on public.training_adjustments (user_id, created_at desc);

-- Recommendations the member accepted or turned down, so they aren't offered again.
create table public.training_recommendation_decisions (
  user_id uuid not null references auth.users (id) on delete cascade,
  recommendation_key text not null check (char_length(recommendation_key) <= 200),
  decision text not null check (decision in ('accepted', 'rejected')),
  decided_at timestamptz not null default now(),
  primary key (user_id, recommendation_key)
);

alter table public.exercise_targets enable row level security;
alter table public.training_adjustments enable row level security;
alter table public.training_recommendation_decisions enable row level security;

-- Members always see and can remove their own rows (also after a downgrade); creating or changing them needs Pro.
create policy exercise_targets_select_own on public.exercise_targets for select to authenticated using (user_id = (select auth.uid()));
create policy exercise_targets_delete_own on public.exercise_targets for delete to authenticated using (user_id = (select auth.uid()));
create policy exercise_targets_insert_own on public.exercise_targets for insert to authenticated
  with check (user_id = (select auth.uid()) and public.has_ai_coach());
create policy exercise_targets_update_own on public.exercise_targets for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()) and public.has_ai_coach());

create policy training_adjustments_select_own on public.training_adjustments for select to authenticated using (user_id = (select auth.uid()));
create policy training_adjustments_delete_own on public.training_adjustments for delete to authenticated using (user_id = (select auth.uid()));
create policy training_adjustments_insert_own on public.training_adjustments for insert to authenticated
  with check (user_id = (select auth.uid()) and public.has_ai_coach());
-- Only the undo mark can change.
create policy training_adjustments_update_own on public.training_adjustments for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
revoke update on public.training_adjustments from authenticated;
grant update (reverted_at) on public.training_adjustments to authenticated;

create policy training_decisions_select_own on public.training_recommendation_decisions for select to authenticated using (user_id = (select auth.uid()));
create policy training_decisions_delete_own on public.training_recommendation_decisions for delete to authenticated using (user_id = (select auth.uid()));
create policy training_decisions_insert_own on public.training_recommendation_decisions for insert to authenticated
  with check (user_id = (select auth.uid()) and public.has_ai_coach());
create policy training_decisions_update_own on public.training_recommendation_decisions for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()) and public.has_ai_coach());

-- ===== supabase/migrations/20261024000028_ai_meal_plans.sql =====
-- Narrow Gate Fitness — personalized AI meal plans (Pro), and the AI usage kinds for the later AI food features.
--
-- The AI only chooses among dishes the app can already measure (the member's recipes and saved meals and the
-- built-in recipes, all with nutrition from the food database) and suggests portions. Every number shown is
-- computed by the app from those values, never by the AI. A generated plan is a draft until the member approves
-- it; only then does it become a normal meal plan (swap, portions, log to diary, grocery list as before).

-- Each AI request is still one of the member's monthly AI messages; the kind says what it was for.
alter table public.ai_usage_events drop constraint if exists ai_usage_events_kind_check;
alter table public.ai_usage_events add constraint ai_usage_events_kind_check
  check (kind in ('chat', 'plan', 'meal_plan', 'food_photo', 'food_explain'));

-- One draft per member, replaced by the next generation, removed when approved or discarded.
create table public.meal_plan_drafts (
  user_id uuid primary key references auth.users (id) on delete cascade,
  start_date date not null,
  days smallint not null check (days in (1, 3, 7)),
  focus text not null check (focus in ('balanced', 'high_protein', 'weight_loss', 'muscle_gain', 'maintenance')),
  notes text check (char_length(notes) <= 300),
  -- Targets the plan was built for, with how they were derived.
  targets jsonb not null check (jsonb_typeof(targets) = 'object' and octet_length(targets::text) <= 2000),
  settings jsonb not null check (jsonb_typeof(settings) = 'object' and octet_length(settings::text) <= 4000),
  -- [{ date, meals: [{ slotIndex, key, portion, by: 'ai' | 'planner' }] }]: dish keys and portions only.
  days_plan jsonb not null check (jsonb_typeof(days_plan) = 'array' and octet_length(days_plan::text) <= 40000),
  summary text check (char_length(summary) <= 1500),
  model text check (char_length(model) <= 100),
  created_at timestamptz not null default now()
);

alter table public.meal_plan_drafts enable row level security;
create policy meal_plan_drafts_select_own on public.meal_plan_drafts for select to authenticated using (user_id = (select auth.uid()));
create policy meal_plan_drafts_delete_own on public.meal_plan_drafts for delete to authenticated using (user_id = (select auth.uid()));
-- Drafts are written by the server after an AI request (service role); members can't plant their own.

-- ===== supabase/migrations/20261024000029_gps_running.sql =====
-- Narrow Gate Fitness — live GPS runs and walks, running goals (basic tracking is free).
--
-- GPS recordings already fit the activities table (source 'gps', route, splits, moving vs elapsed time, private by
-- default, one save per client-generated id). This adds limits on what a recording can store, a note of the signal
-- quality (so gaps are shown honestly), an optional link to the program session a guided run completed, and
-- running goals.

alter table public.activities
  add column gps_quality jsonb check (gps_quality is null or (jsonb_typeof(gps_quality) = 'object' and octet_length(gps_quality::text) <= 1000)),
  add column workout_session_id uuid references public.workout_sessions (id) on delete set null;

-- Keep a single recording to a sane size (the app simplifies routes to at most 2,000 points before saving).
alter table public.activities
  add constraint activities_route_size check (route is null or (jsonb_typeof(route) = 'object' and octet_length(route::text) <= 150000)),
  add constraint activities_splits_size check (splits is null or jsonb_array_length(splits) <= 600);

-- Running goals: a weekly or monthly distance, or a target time for a distance (e.g. 5 km in 28:00).
create table public.running_goals (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  kind text not null check (kind in ('weekly_distance', 'monthly_distance', 'race_time')),
  distance_m numeric(9, 1) not null check (distance_m > 0 and distance_m <= 1000000),
  target_s integer check (target_s is null or target_s between 60 and 172800),
  created_at timestamptz not null default now(),
  archived_at timestamptz,
  check ((kind = 'race_time') = (target_s is not null))
);
create index running_goals_user_idx on public.running_goals (user_id, created_at desc);

alter table public.running_goals enable row level security;
create policy running_goals_select_own on public.running_goals for select to authenticated using (user_id = (select auth.uid()));
create policy running_goals_insert_own on public.running_goals for insert to authenticated with check (user_id = (select auth.uid()));
create policy running_goals_update_own on public.running_goals for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy running_goals_delete_own on public.running_goals for delete to authenticated using (user_id = (select auth.uid()));

-- At most 10 open goals per member.
create or replace function public.enforce_running_goal_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform pg_advisory_xact_lock(hashtextextended('running_goals:' || new.user_id::text, 0));
  if (select count(*) from public.running_goals where user_id = new.user_id and archived_at is null) >= 10 then
    raise exception 'running_goal_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create trigger running_goals_limit before insert on public.running_goals
  for each row execute function public.enforce_running_goal_limit();

-- ===== supabase/migrations/20261024000030_strength_ranks.sql =====
-- Strength ranks on the muscle map (Plus and Pro) compare each lift with a men's or a women's table. The member picks
-- the table on the map itself; the profile's `sex` answer stays limited to calorie estimates, as onboarding says.
-- Ranks are computed from logged workouts when the map is opened and are never stored, like the milestone badges.

alter table public.profiles
  add column if not exists strength_standards text check (strength_standards in ('men', 'women'));

grant update (strength_standards) on public.profiles to authenticated;

-- ===== supabase/migrations/20261024000031_body_scans.sql =====
-- Body Scan (Pro): guided front, side and optional rear photos with optional measurements, kept apart from the
-- ordinary progress photos. Photos live in the PRIVATE `body-scans` bucket under "<uid>/<scan id>/...". Only the
-- owner can read or delete them; there is no admin access anywhere. Nothing here estimates body fat, and no image is
-- sent to the AI coach or any other service.
--
-- New scans need Pro and the member's explicit consent (recorded with the time). Viewing and deleting never need
-- either, so a member who downgrades or withdraws consent can still see and remove what they stored.

alter table public.profiles add column if not exists body_scan_consent_at timestamptz;
grant update (body_scan_consent_at) on public.profiles to authenticated;

create or replace function public.can_add_body_scan()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.has_plan('pro')
    and exists (select 1 from public.profiles p where p.id = auth.uid() and p.body_scan_consent_at is not null);
$$;
revoke all on function public.can_add_body_scan() from public, anon;
grant execute on function public.can_add_body_scan() to authenticated, service_role;

create table public.body_scans (
  -- Generated on the device before upload, so a retried save can't create a second scan.
  id uuid primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  taken_on date not null,
  weight_kg numeric(5, 2) check (weight_kg between 25 and 400),
  -- Measurements entered with the scan are stored in the ordinary measurement history.
  measurement_id uuid references public.measurement_entries (id) on delete set null,
  note text check (char_length(note) <= 280),
  created_at timestamptz not null default now()
);
create index body_scans_user_idx on public.body_scans (user_id, taken_on desc);

create table public.body_scan_photos (
  id uuid primary key default gen_random_uuid(),
  scan_id uuid not null references public.body_scans (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  pose text not null check (pose in ('front', 'side', 'back')),
  storage_path text not null unique check (char_length(storage_path) between 3 and 300),
  created_at timestamptz not null default now(),
  unique (scan_id, pose),
  -- The object must live in the owner's folder for this scan.
  check (split_part(storage_path, '/', 1) = user_id::text),
  check (split_part(storage_path, '/', 2) = scan_id::text)
);
create index body_scan_photos_user_idx on public.body_scan_photos (user_id);

alter table public.body_scans enable row level security;
alter table public.body_scan_photos enable row level security;

create policy body_scans_select_own on public.body_scans
  for select to authenticated using (user_id = (select auth.uid()));
create policy body_scans_delete_own on public.body_scans
  for delete to authenticated using (user_id = (select auth.uid()));
create policy body_scans_insert_own on public.body_scans
  for insert to authenticated with check (user_id = (select auth.uid()) and public.can_add_body_scan());

create policy body_scan_photos_select_own on public.body_scan_photos
  for select to authenticated using (user_id = (select auth.uid()));
create policy body_scan_photos_delete_own on public.body_scan_photos
  for delete to authenticated using (user_id = (select auth.uid()));
create policy body_scan_photos_insert_own on public.body_scan_photos
  for insert to authenticated with check (
    user_id = (select auth.uid())
    and public.can_add_body_scan()
    and exists (select 1 from public.body_scans b where b.id = scan_id and b.user_id = (select auth.uid()))
  );

-- At most 200 scans per member (about four years of weekly scans), checked under a per-member lock.
create or replace function public.body_scan_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform pg_advisory_xact_lock(hashtext('body_scans:' || new.user_id::text));
  if (select count(*) from public.body_scans where user_id = new.user_id) >= 200 then
    raise exception 'body_scan_limit' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
create trigger body_scans_limit before insert on public.body_scans for each row execute function public.body_scan_limit();

-- Storage: private, images only, 8 MB per object. Read and delete your own folder; upload only with Pro and consent.
values ('body-scans', 'body-scans', false, 8388608, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

create policy body_scans_owner_select on storage.objects
  for select to authenticated
  using (bucket_id = 'body-scans' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy body_scans_owner_insert on storage.objects
  for insert to authenticated
  with check (bucket_id = 'body-scans' and (storage.foldername(name))[1] = (select auth.uid())::text and public.can_add_body_scan());
create policy body_scans_owner_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'body-scans' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- ===== supabase/migrations/20261024000032_food_photos.sql =====
-- AI food-photo recognition (Pro). A meal photo is sent to the AI provider only after the member's separate,
-- explicit consent, recorded here with the time. Photos are never stored: the server reads the upload in memory,
-- sends it once, and keeps only the items the member confirms (as ordinary diary entries marked as estimates).

alter table public.profiles add column if not exists food_photo_consent_at timestamptz;
grant update (food_photo_consent_at) on public.profiles to authenticated;

-- Diary entries confirmed from a photo estimate say where they came from.
alter table public.meal_items drop constraint if exists meal_items_source_check;
alter table public.meal_items add constraint meal_items_source_check
  check (source ~ '^(usda:[0-9]{1,10}|off:[0-9]{8,14}|food:[0-9a-f-]{36}|recipe:[0-9a-f-]{36}|app:[a-z0-9-]{1,60}|photo|custom)$');

-- Same reservation as before (one per-member lock re-checks every limit), plus an image cost control: at most
-- 20 food-photo analyses in any 24 hours. Photos also count toward the monthly AI allowance like any request.
create or replace function public.reserve_ai_usage(
  p_user_id uuid,
  p_kind text,
  p_tier text,
  p_chat_limit integer,
  p_plan_limit integer,
  p_smart_limit integer,
  p_per_minute integer
)
returns table (usage_id uuid, model_tier text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_month timestamptz := date_trunc('month', now() at time zone 'utc') at time zone 'utc';
  v_total integer;
  v_plans integer;
  v_smart integer;
  v_recent integer;
  v_tier text := p_tier;
begin
  perform pg_advisory_xact_lock(hashtextextended('ai_usage:' || p_user_id::text, 0));
  select count(*), count(*) filter (where e.kind = 'plan'), count(*) filter (where e.model_tier = 'smart')
    into v_total, v_plans, v_smart
    from public.ai_usage_events e where e.user_id = p_user_id and e.created_at >= v_month;
  select count(*) into v_recent from public.ai_usage_events e where e.user_id = p_user_id and e.created_at >= now() - interval '60 seconds';
  if v_recent >= p_per_minute then
    raise exception 'ai_rate_limited' using errcode = 'P0001';
  end if;
  if v_total >= p_chat_limit then
    raise exception 'ai_quota' using errcode = 'P0001';
  end if;
  if p_kind = 'plan' and (v_plans >= p_plan_limit or v_smart >= p_smart_limit) then
    raise exception 'ai_quota_plan' using errcode = 'P0001';
  end if;
  if p_kind = 'food_photo' and (
    select count(*) from public.ai_usage_events e
    where e.user_id = p_user_id and e.kind = 'food_photo' and e.created_at >= now() - interval '24 hours'
  ) >= 20 then
    raise exception 'ai_quota_photo' using errcode = 'P0001';
  end if;
  -- A chat that would have used the larger model falls back to the fast one once that share is used up.
  if v_tier = 'smart' and v_smart >= p_smart_limit then
    v_tier := 'fast';
  end if;
    values (p_user_id, p_kind, v_tier)
    returning id into usage_id;
  model_tier := v_tier;
  return next;
end;
$$;
revoke all on function public.reserve_ai_usage(uuid, text, text, integer, integer, integer, integer) from public, anon, authenticated;
grant execute on function public.reserve_ai_usage(uuid, text, text, integer, integer, integer, integer) to service_role;

